/**
 * Merge Story/Bug Test Automation PR
 * Merges the PR on branch test/{TICKET_KEY} and moves all linked Test Cases
 * from In Review - Passed/Failed to Passed/Failed.
 */

const { LABELS } = require('./config.js');
var scmModule = require('./common/scm.js');
var configLoader = require('./configLoader.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}


function findPRForStory(scm, storyKey) {
    try {
        const branchName = 'test/' + storyKey;
        const openList = scm.listPrs('open');
        const openMatch = (Array.isArray(openList) ? openList : []).find(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName && !pr.merged_at;
        });
        if (openMatch) return { pr: openMatch, merged: false };

        const closedList = scm.listPrs('closed');
        const mergedMatch = (Array.isArray(closedList) ? closedList : []).find(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName && pr.merged_at;
        });
        if (mergedMatch) return { pr: mergedMatch, merged: true };

        return null;
    } catch (e) {
        console.error('Failed to list PRs:', e);
        return null;
    }
}

function releaseLock(storyKey, customParams) {
    const removeLabel = customParams && customParams.removeLabel;
    if (removeLabel && storyKey) {
        try { getTracker().removeLabel(storyKey, removeLabel); } catch (e) {}
    }
}

// ── gh-964: pure check-run classification (extracted from checkCiStatus) ──

/**
 * Normalizes the raw getCommitCheckRuns payload into a check-run array.
 * Accepts a bare array, a { check_runs: [...] } wrapper, or a JSON string
 * of either shape; anything else yields [].
 */
function normalizeCheckRuns(raw) {
    if (typeof raw === 'string') {
        try { raw = JSON.parse(raw); } catch (e) {}
    }
    return Array.isArray(raw) ? raw
        : (raw && raw.check_runs ? raw.check_runs : []);
}

function isPendingCheckStatus(status) {
    return status === 'in_progress' || status === 'queued' ||
        status === 'pending' || status === 'waiting';
}

function isFailedCheckConclusion(conclusion) {
    return conclusion === 'failure' || conclusion === 'timed_out' ||
        conclusion === 'action_required';
}

/**
 * Pure classification of a check-run list: which checks are still running,
 * which failed (and their names), and how many there were in total.
 */
function classifyCheckRuns(checkRuns) {
    var result = { inProgress: false, failed: false, failedNames: [], total: checkRuns.length };
    checkRuns.forEach(function(c) {
        var status = (c.status || '').toLowerCase();
        var conclusion = (c.conclusion || '').toLowerCase();
        if (isPendingCheckStatus(status)) {
            result.inProgress = true;
        }
        if (isFailedCheckConclusion(conclusion)) {
            result.failed = true;
            if (c.name) result.failedNames.push(c.name);
        }
    });
    return result;
}

function checkCiStatus(scm, headSha) {
    var result = { inProgress: false, failed: false, failedNames: [], total: 0 };
    if (!scm || typeof scm.getCommitCheckRuns !== 'function' || !headSha) {
        return result;
    }
    try {
        var raw = scm.getCommitCheckRuns(headSha);
        result = classifyCheckRuns(normalizeCheckRuns(raw));
    } catch (e) {
        console.warn('Could not determine CI status:', e);
    }
    return result;
}

function fetchLinkedTestCases(storyKey, testCaseType) {
    // JQL text: provider-specific query (WIQL on ado)
    var jql = 'issue in linkedIssues("' + storyKey + '") AND issuetype = "' + testCaseType + '"';
    try {
        // gh-916: in label mode the final-status gate also reads stage markers, so labels are requested;
        // 'none' mode sends the exact same fields list as before.
        var fields = ['key', 'status'];
        if (getTracker().stageFallback() === 'label') fields = fields.concat(['labels']);
        return getTracker().searchIssues(jql, { maxResults: 100, fields: fields }) || [];
    } catch (e) {
        console.warn('Failed to fetch linked Test Cases for merge:', e);
        return [];
    }
}

function resolveFinalStatus(tc, jiraConfig, tracker) {
    // gh-916: hasStage also accepts the stage_<key> marker a rejected In Review - Passed/Failed
    // transition left (jira.stageFallback 'label'); 'none' mode compares the status only.
    if (tracker.hasStage(tc, 'IN_REVIEW_PASSED', jiraConfig.statuses.IN_REVIEW_PASSED)) return jiraConfig.statuses.PASSED;
    if (tracker.hasStage(tc, 'IN_REVIEW_FAILED', jiraConfig.statuses.IN_REVIEW_FAILED)) return jiraConfig.statuses.FAILED;
    return null;
}

function moveLinkedTestCases(storyKey, testCaseType, jiraConfig) {
    var testCases = fetchLinkedTestCases(storyKey, testCaseType);
    var moved = 0;
    var skipped = 0;
    testCases.forEach(function(tc) {
        var finalStatus = resolveFinalStatus(tc, jiraConfig, getTracker());
        if (!finalStatus) {
            console.log('Skipping linked TC', tc.key, '— current status', tc.fields && tc.fields.status ? tc.fields.status.name : '');
            skipped++;
            return;
        }
        try {
            // gh-916: Passed/Failed can be tag-only (restricted ADO workflows) — stage-label fallback.
            var result = getTracker().moveToStatusOrMark(tc.key, finalStatus,
                finalStatus === jiraConfig.statuses.PASSED ? 'PASSED' : 'FAILED');
            if (result.moved || result.marked) {
                console.log('✅ Moved', tc.key, 'to', finalStatus);
                moved++;
            } else {
                skipped++;
            }
        } catch (e) {
            console.warn('Failed to move', tc.key, 'to', finalStatus, ':', e);
            skipped++;
        }
    });
    return { moved: moved, skipped: skipped, total: testCases.length };
}

function finalizeAlreadyMergedPR(params, scm, storyKey, pr, testCaseType, customParams, jiraConfig) {
    const prNumber = pr.number;
    const prUrl = pr.html_url;
    console.log('PR #' + prNumber + ' already merged for story ' + storyKey + ' — finalizing');

    var issueType = params.ticket && params.ticket.fields &&
        params.ticket.fields.issuetype && params.ticket.fields.issuetype.name;

    var tcResult = moveLinkedTestCases(storyKey, testCaseType, jiraConfig);

    // Bug stays In Testing; bug_done_check will move it to Done only when all
    // directly linked Test Cases are Passed. Moving it here allowed bugs to be
    // closed while their acceptance tests were still failing.

    try {
        getTracker().removeLabel(storyKey, LABELS.PR_APPROVED);
    } catch (e) {
        console.warn('Could not remove pr_approved label:', e);
    }
    try {
        getTracker().removeLabel(storyKey, LABELS.TEST_PR_MERGED);
    } catch (e) {
        console.warn('Could not remove test_pr_merged label:', e);
    }
    try {
        getTracker().addLabel(storyKey, LABELS.TEST_PR_FINALIZED);
        console.log('Added test_pr_finalized label to', storyKey);
    } catch (e) {
        console.warn('Could not add test_pr_finalized label:', e);
    }

    var ticketLabel = issueType || 'Story';
    getTracker().postComment(storyKey, 'h3. ✅ ' + ticketLabel + ' Test PR Already Merged\n\n' +
            'PR [#' + prNumber + '|' + prUrl + '] for branch {code}test/' + storyKey + '{code} was already merged.\n\n' +
            'Linked Test Cases moved to final status: *' + tcResult.moved + '* moved, *' + tcResult.skipped + '* skipped.');

    postTokenUsageCommentsSafe(params, storyKey);

    return true;
}

// ── gh-964: pure merge-decision helpers (extracted from attemptMerge) ──

function resolveCustomParams(params) {
    return (params.jobParams && params.jobParams.customParams) || params.customParams || {};
}

// Mergeable states that mean "GitHub has not finished computing / CI gates the
// merge" — the CI check-run gate below decides between failed / running / retry.
var UNDETERMINED_MERGE_STATES = {
    unknown: true,
    blocked: true,
    unstable: true,
    checking: true,
    unchecked: true,
    preparing: true,
    ci_must_pass: true,
    ci_still_running: true
};

function isUndeterminedMergeState(mergeable, mergeableState) {
    return mergeable === null || !!UNDETERMINED_MERGE_STATES[mergeableState];
}

function isConflictMergeState(mergeable, mergeableState) {
    return (mergeable === false && mergeableState === 'dirty') ||
        mergeableState === 'cannot_be_merged' ||
        mergeableState === 'conflict';
}

/**
 * Pure decision over a classified CI status: 'ci_failed' when a check failed,
 * 'ci_running' while checks are pending or none are known at all, null when
 * every check has passed (callers map null to their own default action).
 */
function decideCiBlock(ci) {
    if (ci.failed) return 'ci_failed';
    if (ci.inProgress || ci.total === 0) return 'ci_running';
    return null;
}

/**
 * Pure classification of a merge error message: the message itself, whether it
 * denotes a conflict, and whether it looks like a CI-required/blocking failure
 * worth re-checking the check runs for.
 */
function classifyMergeError(mergeErr) {
    var errMsg = mergeErr ? String(mergeErr) : '';
    return {
        errMsg: errMsg,
        isConflict: errMsg.toLowerCase().indexOf('conflict') !== -1,
        isCIBlocking: errMsg.indexOf('blocked') !== -1 ||
            errMsg.indexOf('422') !== -1 ||
            errMsg.indexOf('405') !== -1
    };
}

/**
 * Reads PR merge details, tolerating provider errors (logged, details stay
 * null so the merge state is treated as undetermined downstream).
 */
function readPrMergeDetail(scm, prNumber) {
    var detail = { mergeable: null, mergeableState: null, headSha: null };
    try {
        const prDetail = scm.getPr(prNumber);
        detail.mergeable = prDetail && prDetail.mergeable;
        detail.mergeableState = prDetail && prDetail.mergeable_state;
        detail.headSha = prDetail && prDetail.head && prDetail.head.sha;
        console.log('PR mergeable: ' + detail.mergeable + ', state: ' + detail.mergeableState +
            ', headSha: ' + (detail.headSha ? detail.headSha.substring(0, 8) : 'n/a'));
    } catch (e) {
        console.warn('Could not get PR details, will attempt merge anyway:', e);
    }
    return detail;
}

/**
 * Best-effort base-branch update for a behind PR; failures are logged and
 * swallowed — the caller reports 'behind' either way so the SM retries.
 */
function requestBranchUpdate(scm, prNumber, repoInfo) {
    try {
        if (scm.updateBranch) {
            scm.updateBranch(prNumber, repoInfo.owner, repoInfo.repo);
        } else {
            throw new Error('SCM provider does not support updateBranch');
        }
    } catch (updateErr) {
        console.warn('Could not update branch:', updateErr);
    }
}

/**
 * Shared tail of both finalize paths: post the token-usage summary comments,
 * logging and swallowing provider errors.
 */
function postTokenUsageCommentsSafe(params, storyKey) {
    try {
        tokenUsageComment.postTokenUsageComments(storyKey, { initiator: params.initiator, customParams: tokenUsageComment.customParamsOf(params) });
    } catch (e) {
        console.warn('Failed to post token usage comments:', e);
    }
}

/**
 * Everything that happens after a successful squash merge: label cleanup on
 * the PR and the ticket, the merge summary comment, token-usage comments, and
 * moving the linked Test Cases to their final status. Returns the merged
 * result object (with tcResult) for the caller.
 */
function finalizeMergedPR(params, scm, storyKey, prNumber, prUrl, testCaseType, jiraConfig, issueType) {
    console.log('✅ PR #' + prNumber + ' merged successfully');

    try { scm.removeLabel(prNumber, LABELS.PR_APPROVED); } catch (e) {}

    var tcResult = moveLinkedTestCases(storyKey, testCaseType, jiraConfig);

    try {
        getTracker().removeLabel(storyKey, LABELS.PR_APPROVED);
        console.log('Removed pr_approved label from Jira ticket');
    } catch (e) {
        console.warn('Could not remove pr_approved from Jira ticket:', e);
    }
    try {
        getTracker().removeLabel(storyKey, LABELS.TEST_PR_MERGED);
    } catch (e) {
        console.warn('Could not remove test_pr_merged label:', e);
    }
    try {
        getTracker().addLabel(storyKey, LABELS.TEST_PR_FINALIZED);
        console.log('Added test_pr_finalized label to', storyKey);
    } catch (e) {
        console.warn('Could not add test_pr_finalized label:', e);
    }

    var ticketLabel = issueType || 'Story';
    getTracker().postComment(storyKey, 'h3. ✅ ' + ticketLabel + ' Test PR Merged\n\n' +
            'PR [#' + prNumber + '|' + prUrl + '] for branch {code}test/' + storyKey + '{code} was merged.\n\n' +
            'Linked Test Cases moved to final status: *' + tcResult.moved + '* moved, *' + tcResult.skipped + '* skipped.');

    postTokenUsageCommentsSafe(params, storyKey);

    return { success: true, reason: 'merged', prNumber: prNumber, prUrl: prUrl, tcResult: tcResult };
}

/**
 * Attempts to merge/finalize the test-automation PR for the given ticket.
 * Does NOT move the ticket to a different status and does NOT release SM locks.
 *
 * Returns an object:
 *   { success: true, noPr: true }                              — no PR found, nothing to do
 *   { success: true, alreadyMerged: true, prNumber, prUrl }    — PR already merged, finalized
 *   { success: true, reason: 'merged', prNumber, prUrl, tcResult } — PR merged now
 *   { success: false, reason: 'missing_key'|'no_repo'|'no_pr'|     — could not proceed
 *                             'ci_running'|'not_ready'|'behind'|
 *                             'conflict'|'ci_failed'|'merge_failed',
 *     prNumber?, prUrl?, failedNames?, error? }
 */
function attemptMerge(params) {
    const storyKey = params.ticket && params.ticket.key;
    if (!storyKey) {
        console.error('No storyKey provided');
        return { success: false, reason: 'missing_key' };
    }

    var config = configLoader.loadProjectConfig(params.jobParams || params);
    var jiraConfig = config.jira;
    var scm = scmModule.createScm(config);
    var customParams = resolveCustomParams(params);
    initTracker(config, customParams);
    var testCaseType = jiraConfig.issueTypes.TEST_CASE || 'Test Case';
    var issueType = params.ticket && params.ticket.fields &&
        params.ticket.fields.issuetype && params.ticket.fields.issuetype.name;

    const repoInfo = scm.getRemoteRepoInfo();
    if (!repoInfo) {
        console.error('Could not determine owner/repo');
        return { success: false, reason: 'no_repo' };
    }

    const found = findPRForStory(scm, storyKey);
    if (!found) {
        console.log('No open or merged PR found for', storyKey, '— nothing to merge');
        return { success: true, noPr: true };
    }

    if (found.merged) {
        finalizeAlreadyMergedPR(params, scm, storyKey, found.pr, testCaseType, customParams, jiraConfig);
        return {
            success: true,
            alreadyMerged: true,
            prNumber: found.pr.number,
            prUrl: found.pr.html_url,
            reason: 'already_merged'
        };
    }

    const pr = found.pr;
    const prNumber = pr.number;
    const prUrl = pr.html_url;
    console.log('Found PR #' + prNumber + ' for story ' + storyKey);

    var prDetail = readPrMergeDetail(scm, prNumber);
    var mergeable = prDetail.mergeable;
    var mergeableState = prDetail.mergeableState;
    var headSha = prDetail.headSha;

    if (isUndeterminedMergeState(mergeable, mergeableState)) {
        const ci = checkCiStatus(scm, headSha);
        const block = decideCiBlock(ci);
        if (block === 'ci_failed') {
            console.log('PR #' + prNumber + ' CI checks failed');
            return { success: false, reason: 'ci_failed', prNumber, prUrl, failedNames: ci.failedNames };
        }
        if (block === 'ci_running') {
            console.log('PR not ready to merge (' + mergeableState + ') — checks still running or unknown — will retry');
            return { success: false, reason: 'ci_running', prNumber, prUrl };
        }
        console.log('PR not ready to merge (' + mergeableState + ') — will retry');
        return { success: false, reason: 'not_ready', prNumber, prUrl };
    }

    if (mergeableState === 'behind') {
        console.log('PR branch is behind base — requesting branch update');
        requestBranchUpdate(scm, prNumber, repoInfo);
        return { success: false, reason: 'behind', prNumber, prUrl };
    }

    if (isConflictMergeState(mergeable, mergeableState)) {
        console.log('PR #' + prNumber + ' has merge conflict');
        return { success: false, reason: 'conflict', prNumber, prUrl };
    }

    try {
        scm.mergePr(prNumber, 'squash');
        return finalizeMergedPR(params, scm, storyKey, prNumber, prUrl, testCaseType, jiraConfig, issueType);
    } catch (mergeErr) {
        console.warn('Merge failed:', mergeErr);
        const errInfo = classifyMergeError(mergeErr);

        if (!errInfo.isConflict && (errInfo.isCIBlocking || errInfo.errMsg === '')) {
            const ci = checkCiStatus(scm, headSha);
            const block = decideCiBlock(ci);
            if (block === 'ci_failed') {
                return { success: false, reason: 'ci_failed', prNumber, prUrl, failedNames: ci.failedNames };
            }
            if (block === 'ci_running') {
                console.log('Merge blocked temporarily — checks still running or unknown — will retry');
                return { success: false, reason: 'ci_running', prNumber, prUrl };
            }
        }

        return { success: false, reason: errInfo.isConflict ? 'conflict' : 'merge_failed', prNumber, prUrl, error: errInfo.errMsg };
    }
}

function action(params) {
    const storyKey = params.ticket && params.ticket.key;
    var customParams = resolveCustomParams(params);
    var config = configLoader.loadProjectConfig(params.jobParams || params);
    initTracker(config, customParams);

    // Some callers (e.g. checkBugTestsPassed.js) only need the merge attempt
    // without the surrounding finalize/retry logic. The GraalJS loader may return
    // the action function as the module default, so we also support an explicit
    // flag instead of relying on attemptMerge being reachable as a named export.
    if (customParams.onlyAttemptMerge) {
        return attemptMerge(params);
    }

    if (!storyKey) {
        console.error('No storyKey provided');
        return false;
    }

    var issueType = params.ticket && params.ticket.fields &&
        params.ticket.fields.issuetype && params.ticket.fields.issuetype.name;

    var jiraConfig = config.jira;
    var scm = scmModule.createScm(config);

    const mergeResult = attemptMerge(params);

    if (mergeResult.success) {
        releaseLock(storyKey, customParams);
        return true;
    }

    const prNumber = mergeResult.prNumber;
    const prUrl = mergeResult.prUrl;

    if (mergeResult.reason === 'ci_running' || mergeResult.reason === 'behind' || mergeResult.reason === 'not_ready') {
        // Keep lock; SM will retry on the next cycle.
        return false;
    }

    if (mergeResult.reason === 'missing_key' || mergeResult.reason === 'no_repo') {
        releaseLock(storyKey, customParams);
        return false;
    }

    // Conflict, CI failure, or other merge failure — move ticket to test-automation rework.
    console.log('Test-automation PR merge failed (' + mergeResult.reason + ') — moving ticket to In Rework');

    if (prNumber) {
        try { scm.removeLabel(prNumber, LABELS.PR_APPROVED); } catch (e) {}
    }
    try { getTracker().removeLabel(storyKey, LABELS.PR_APPROVED); } catch (e) {}
    try { getTracker().addLabel(storyKey, LABELS.TEST_PR_REWORK_NEEDED); } catch (e) {}
    var reworkSkipLabel = issueType === jiraConfig.issueTypes.BUG ? 'sm_bug_test_rework_triggered' : 'sm_story_test_rework_triggered';
    try { getTracker().removeLabel(storyKey, reworkSkipLabel); } catch (e) {}

    releaseLock(storyKey, customParams);

    var checksList = mergeResult.failedNames && mergeResult.failedNames.length ? mergeResult.failedNames.join(', ') : 'unknown';
    var isConflict = mergeResult.reason === 'conflict';
    var panelTitle = isConflict ? 'MERGE CONFLICT' : 'MERGE FAILED';
    var reasonText = isConflict ? 'merge conflict' : 'CI checks failing or PR not mergeable';
    if (mergeResult.reason === 'ci_failed' && mergeResult.failedNames) {
        reasonText = 'required checks failed: ' + checksList;
    }
    getTracker().postComment(storyKey, '{panel:bgColor=#FFEBE6|borderColor=#DE350B}⚠️ *' + panelTitle + '* — Could not merge PR #' + (prNumber || 'unknown') + ': ' + reasonText + '.\n\n' + (prUrl ? '[View PR|' + prUrl + ']' : '') + '{panel}');
    getTracker().moveToStatus(storyKey, jiraConfig.statuses.IN_REWORK);
    return true;
}

// Expose attemptMerge on the action function as well, so callers that receive
// the action as the module default (common in the GraalJS/SM loader) can still
// invoke attemptMerge directly.
action.attemptMerge = attemptMerge;

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        attemptMerge: attemptMerge,
        // gh-964: pure helpers extracted from checkCiStatus / attemptMerge —
        // exported for direct unit testing (additive surface, same signatures).
        normalizeCheckRuns: normalizeCheckRuns,
        classifyCheckRuns: classifyCheckRuns,
        isPendingCheckStatus: isPendingCheckStatus,
        isFailedCheckConclusion: isFailedCheckConclusion,
        decideCiBlock: decideCiBlock,
        classifyMergeError: classifyMergeError,
        isUndeterminedMergeState: isUndeterminedMergeState,
        isConflictMergeState: isConflictMergeState,
        resolveCustomParams: resolveCustomParams
    };
}

/**
 * recoverStuckTestCase.js
 *
 * Local-execution recovery for Test Cases stuck in "In Development".
 *
 * When test_case_automation creates a PR but the postJSAction fails to
 * transition the ticket (agent crash, timeout, etc.), the TC stays
 * in "In Development" with no SM rule to advance it.
 *
 * This handler:
 *  1. Looks for an open PR matching the ticket key.
 *  2. If PR exists and CONFLICTING → move ticket to "In Rework" so
 *     pr_test_automation_rework resolves the conflict.
 *  3. If PR exists and is mergeable/clean → move to "In Review - Passed"
 *     so the review agent picks it up.
 *  4. If no open PR exists → move back to "Backlog" and remove the
 *     sm_test_automation_triggered label so automation re-triggers.
 */

var scmModule = require('./common/scm.js');
var configLoader = require('./configLoader.js');
const { LABELS } = require('./config.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var trackersModule = require('./common/trackers.js');

function findPRForTicket(scm, ticketKey) {
    try {
        var prList = scm.listPrs('open');
        var matched = (Array.isArray(prList) ? prList : []).find(function(pr) {
            var titleMatch = pr.title && pr.title.indexOf(ticketKey) !== -1;
            var branchMatch = pr.head && pr.head.ref && pr.head.ref.indexOf(ticketKey) !== -1;
            return titleMatch || branchMatch;
        });
        return matched || null;
    } catch (e) {
        console.error('Failed to list PRs:', e);
        return null;
    }
}

function action(params) {
    var ticketKey = params.ticket && params.ticket.key;
    var config = configLoader.loadProjectConfig(params.jobParams || params || {});
    var jiraConfig = config.jira;
    var tracker = trackersModule.createTracker(config, (params.jobParams && params.jobParams.customParams) || params.customParams || {});

    if (!ticketKey) {
        console.error('No ticket key found');
        return { success: false, error: 'missing ticket key' };
    }

    console.log('Recovering stuck Test Case:', ticketKey);

    var scm = scmModule.createScm(config);
    var pr = findPRForTicket(scm, ticketKey);

    if (!pr) {
        console.log('No open PR found for', ticketKey, '— moving back to Backlog');
        try {
            tracker.moveToStatus(ticketKey, jiraConfig.statuses.BACKLOG);
            console.log('✅ Moved', ticketKey, 'to Backlog');
        } catch (e) {
            console.error('Failed to move to Backlog:', e);
        }
        // Remove automation label so SM can re-trigger
        try { tracker.removeLabel(ticketKey, 'sm_test_automation_triggered'); } catch (e) {}
        tracker.postComment(ticketKey, '🔄 *Recovery*: Test Case was stuck in "In Development" with no open PR. Moved back to Backlog for re-automation.'
        );
        return { success: true, action: 'moved_to_backlog', ticketKey: ticketKey };
    }

    console.log('Found open PR #' + pr.number + ': ' + pr.title);

    // Get detailed PR info to check merge state
    var prDetail;
    try {
        prDetail = scm.getPr(pr.number);
    } catch (e) {
        console.error('Failed to get PR details:', e);
        prDetail = pr;
    }

    var mergeableState = prDetail && (prDetail.mergeable_state || prDetail.mergeableState || '');
    var mergeable = prDetail && prDetail.mergeable;
    console.log('PR #' + pr.number + ' mergeable=' + mergeable + ' state=' + mergeableState);

    if (mergeableState === 'dirty' || mergeableState === 'conflicting' || mergeable === false) {
        console.log('PR has conflicts — moving ticket to In Rework');
        try {
            tracker.moveToStatus(ticketKey, jiraConfig.statuses.IN_REWORK);
            console.log('✅ Moved', ticketKey, 'to In Rework');
        } catch (e) {
            console.error('Failed to move to In Rework:', e);
        }
        // Remove stale labels so rework agent can pick it up
        try { tracker.removeLabel(ticketKey, 'sm_test_rework_triggered'); } catch (e) {}
        try { tracker.removeLabel(ticketKey, 'sm_test_automation_triggered'); } catch (e) {}
        tracker.postComment(ticketKey, '🔄 *Recovery*: Test Case was stuck in "In Development" with a conflicting PR #' + pr.number + '. Moved to In Rework for conflict resolution.'
        );
        return { success: true, action: 'moved_to_rework', ticketKey: ticketKey, prNumber: pr.number };
    }

    // PR is clean/mergeable — move to In Review - Passed for review
    console.log('PR looks clean — moving ticket to In Review - Passed');
    try {
        // gh-916: IN_REVIEW_PASSED can be tag-only (restricted ADO workflows) — stage-label fallback.
        var moveResult = tracker.moveToStatusOrMark(ticketKey, jiraConfig.statuses.IN_REVIEW_PASSED, 'IN_REVIEW_PASSED');
        if (moveResult.moved || moveResult.marked) {
            console.log('✅ Moved', ticketKey, 'to In Review - Passed');
        }
    } catch (e) {
        console.error('Failed to move to In Review - Passed:', e);
    }
    try { tracker.removeLabel(ticketKey, 'sm_test_automation_triggered'); } catch (e) {}
    tracker.postComment(ticketKey, '🔄 *Recovery*: Test Case was stuck in "In Development" with clean PR #' + pr.number + '. Moved to In Review - Passed for code review.'
    );

    // Post token usage summary comments (e.g. [story_acceptance_criteria]: {...}) if any provider
    // wrote outputs/*_usage.json during the agent run.
    try {
        tokenUsageComment.postTokenUsageComments(ticketKey, { initiator: params.initiator, tracker: tracker });
    } catch (e) {
        console.warn('Failed to post token usage comments:', e);
    }

    return { success: true, action: 'moved_to_review', ticketKey: ticketKey, prNumber: pr.number };
}

module.exports = { action };

/**
 * Prepare Test PR For Review Action (preJSAction for test-automation review agents)
 * Same as preparePRForReview.js but specifically targets test/{TICKET-KEY} branches,
 * not feature ai/{TICKET-KEY} branches.
 *
 * Runs as preJSAction so that returning `false` skips the whole agent when the PR is
 * already merged or has no changes.
 */

var configLoader = require('./configLoader.js');
const gh = require('./common/githubHelpers.js');
const gitOps = require('./common/gitOps.js');
var prHelper = require('./common/pullRequest.js');
const { LABELS } = require('./config.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var _trackerCtx = { config: null, customParams: {} };
var _trackerInst = null;
function initTracker(config, customParams) {
    _trackerCtx = { config: config || null, customParams: customParams || {} };
    _trackerInst = null;
}
function getTracker() {
    if (!_trackerInst) _trackerInst = trackersModule.createTracker(_trackerCtx.config, _trackerCtx.customParams);
    return _trackerInst;
}


function getTicketKey(params) {
    if (params.ticket && params.ticket.key) {
        return params.ticket.key;
    }
    if (params.inputFolderPath) {
        return params.inputFolderPath.split('/').pop();
    }
    if (params.jobParams && params.jobParams.inputFolderPath) {
        return params.jobParams.inputFolderPath.split('/').pop();
    }
    throw new Error('Cannot determine ticket key from params.ticket.key or params.inputFolderPath');
}

function getInputFolder(params, ticketKey) {
    if (params.inputFolderPath) {
        return params.inputFolderPath;
    }
    return 'input/' + ticketKey;
}

function ensureInputFolder(inputFolder) {
    try {
        cli_execute_command({ command: 'bash -c "mkdir -p ' + inputFolder + '"' });
    } catch (e) {
        console.warn('Could not create input folder:', e);
    }
}

function findTestPRForTicket(scm, ticketKey) {
    try {
        const branchName = 'test/' + ticketKey;
        console.log('Searching for PR on branch:', branchName);

        const openPRs = scm.listPrs('open');
        const openMatch = openPRs.filter(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName;
        });
        if (openMatch.length > 0) {
            console.log('Found open test PR #' + openMatch[0].number);
            return { pr: openMatch[0], merged: false };
        }

        const closedPRs = scm.listPrs('closed');
        const mergedMatch = closedPRs.filter(function(pr) {
            return pr.head && pr.head.ref && pr.head.ref === branchName && pr.merged_at;
        });
        if (mergedMatch.length > 0) {
            console.log('Found already-merged test PR #' + mergedMatch[0].number);
            return { pr: mergedMatch[0], merged: true };
        }

        console.warn('No PR found for test branch:', branchName);
        return null;
    } catch (e) {
        console.error('Failed to find test PR:', e);
        return null;
    }
}

function clearStaleReviewOutputs() {
    try {
        cli_execute_command({
            command: 'rm -f outputs/pr_review.json outputs/response.md outputs/pr_review_general.md && rm -rf outputs/pr_review_comments'
        });
        console.log('✅ Cleared stale review outputs');
    } catch (e) {
        console.warn('Could not clear stale review outputs:', e);
    }
}

// gh-965: ticket summary for the PR title — falls back to the ticket key when
// the tracker issue or its summary is unavailable.
function prTitleSummary(ticket, ticketKey) {
    return ticket && ticket.fields ? (ticket.fields.summary || ticketKey) : ticketKey;
}

// gh-965: creates the review PR for an existing test branch and re-fetches it
// so downstream code gets a consistent PR shape from the SCM. Throws on failure.
function createReviewPrForBranch(scm, ticketKey, branchName, config) {
    const ticket = getTracker().getIssue(ticketKey);
    const prTitle = configLoader.formatTemplate(config.formats.prTitle.testAutomation,
        {ticketKey: ticketKey, ticketSummary: prTitleSummary(ticket, ticketKey)});

    const prResult = prHelper.createPullRequest({
        scm: scm,
        title: prTitle,
        branchName: branchName,
        baseBranch: config.git.baseBranch,
        // gh-737: merge bot links approved issues via 'Closes #N' —
        // emit it by construction on this auto-created review PR.
        ticketKey: ticketKey,
        bodyContent: 'Auto-created PR for test automation review.\n\nTicket: ' + ticketKey
    });
    if (!prResult || !prResult.success) {
        throw new Error((prResult && prResult.error) || 'Failed to create PR/MR');
    }

    console.log('✅ Created new PR/MR for review:', prResult.prUrl || '(URL unknown)');
    const found = findTestPRForTicket(scm, ticketKey);
    if (!found) {
        throw new Error('PR was created but could not be found immediately after creation');
    }
    return found;
}

// gh-965: the "no open/merged PR" decision. Re-automation when the remote
// branch is gone; otherwise create the review PR. Returns { found } to proceed
// with review, or { result: false } when action() must abort.
function ensureReviewPrExists(scm, ticketKey, config, jiraConfig, issueType) {
    const branchName = 'test/' + ticketKey;
    console.log('No PR found. Checking if branch exists on remote:', branchName);

    if (!remoteBranchExistsOnOrigin(branchName)) {
        // No branch at all — needs re-automation from scratch
        const err = 'No test PR and no remote branch found for test/' + ticketKey + '. Ticket needs re-automation.';
        try {
            getTracker().postComment(ticketKey, 'h3. ⚠️ Test PR Review Setup Failed\n\n' + err + '\n\n_Moving to In Rework so it can be re-automated._');
            getTracker().moveToStatus(ticketKey, jiraConfig.statuses.IN_REWORK);
        } catch (e) {}
        return { result: false };
    }

    // Branch exists — create a new PR/MR so review can proceed
    console.log('Branch exists but no PR — creating PR for review...');
    try {
        return { found: createReviewPrForBranch(scm, ticketKey, branchName, config) };
    } catch (createErr) {
        if (isNoCommitsError(createErr)) {
            console.log('Branch test/' + ticketKey + ' has no commits ahead of main — test code is already merged.');
            finalizeAlreadyMergedTestCase(ticketKey, branchName, issueType, jiraConfig);
            return { result: false };
        }
        postReviewSetupFailed(ticketKey,
            'Branch test/' + ticketKey + ' exists but could not create PR: ' + createErr.toString(),
            '_Review cancelled._');
        return { result: false };
    }
}

// gh-965: PR already merged — move ticket to final status without re-reviewing.
function handleAlreadyMergedPr(ticketKey, pr, issueType, jiraConfig) {
    markTestPrMerged(ticketKey);
    try {
        const ticket = getTracker().getIssue(ticketKey);
        const finalStatus = resolveFinalStatus(ticket, issueType, jiraConfig, getTracker());
        // gh-916: the final status (Passed/Failed/In Testing) can be tag-only — stage-label fallback.
        const moved = getTracker().moveToStatusOrMark(ticketKey, finalStatus,
            issueType === jiraConfig.issueTypes.TEST_CASE
                ? (finalStatus === jiraConfig.statuses.FAILED ? 'FAILED' : 'PASSED')
                : 'IN_TESTING');
        if (moved.moved || moved.marked) {
            getTracker().postComment(ticketKey, 'h3. ✅ Test PR Already Merged\n\n' +
                    'PR [#' + pr.number + '|' + pr.html_url + '] for branch {code}test/' + ticketKey + '{code} was already merged.\n\n' +
                    'Skipping re-review — moved ticket to *' + finalStatus + '*.');
            console.log('✅ PR already merged — moved', ticketKey, 'to', finalStatus);
        }
    } catch (e) {
        console.warn('Failed to handle already-merged PR:', e);
    }
}

// gh-965: a PR whose diff is empty carries no test code to review.
function hasNoChanges(prDetails) {
    var changedFiles = prDetails.changed_files;
    return typeof changedFiles === 'number' && changedFiles === 0;
}

function isNoCommitsError(error) {
    const msg = error && error.toString ? error.toString() : String(error);
    return msg.indexOf('No commits between') !== -1 ||
           msg.indexOf('no commits between') !== -1;
}

// gh-965: setup-failure comment shared by every abort-before-review path.
function postReviewSetupFailed(ticketKey, err, note) {
    try {
        getTracker().postComment(ticketKey, 'h3. ⚠️ Test PR Review Setup Failed\n\n' + err + '\n\n' + note);
    } catch (e) {}
}

// gh-965: probes origin for the test branch via ls-remote (stderr-noise tolerant:
// the check is on a real refs/heads/<name> line, not capture non-emptiness).
function remoteBranchExistsOnOrigin(branchName) {
    try {
        const lsOutput = cli_execute_command({ command: 'git ls-remote --heads origin ' + branchName }) || '';
        return lsOutput.indexOf('refs/heads/' + branchName) !== -1;
    } catch (e) {
        console.warn('Could not check remote branch:', e);
        return false;
    }
}

function getIssueType(params) {
    try {
        return params.ticket.fields.issuetype.name;
    } catch (e) {
        return null;
    }
}

// ── gh-1077 extracted pure helpers (parse/build/decide) ─────────────────────

function isWipPrTitle(title) {
    return /^\s*(WIP|DRAFT)\b/i.test(title);
}

// The PR itself is WIP/draft: an explicit draft flag or a WIP/DRAFT title prefix.
function isWipPr(pr) {
    return !!pr && (!!pr.draft || (!!pr.title && isWipPrTitle(pr.title)));
}

// ADO labels arrive as {value: [...]}; jira/github as a plain array.
// Returns null when the ticket carries no labels at all.
function ticketLabels(ticket) {
    if (!ticket || !ticket.labels) {
        return null;
    }
    return Array.isArray(ticket.labels) ? ticket.labels : (ticket.labels.value || []);
}

function isWipLabel(label) {
    return /_(wip|draft)$/i.test(label) || /^(wip|draft)$/i.test(label);
}

function hasWipTicketLabel(ticket) {
    const labels = ticketLabels(ticket);
    if (!labels) {
        return false;
    }
    for (var i = 0; i < labels.length; i++) {
        if (isWipLabel(labels[i])) {
            return true;
        }
    }
    return false;
}

function isWip(pr, ticket) {
    if (isWipPr(pr)) {
        return true;
    }
    if (hasWipTicketLabel(ticket)) {
        return true;
    }
    return false;
}

function resolveFinalStatus(ticket, issueType, jiraConfig, tracker) {
    // Test Cases finish in Passed/Failed; Stories and Bugs stay in In Testing
    // so the done-check agents (checkStoryTestsPassed / checkBugTestsPassed)
    // can evaluate all linked Test Cases and move to Done / Bug To Fix / Ready For Testing.
    // gh-916: hasStage also accepts the stage_<key> marker a rejected In Review - Failed
    // transition left (jira.stageFallback 'label'); 'none' mode compares the status only.
    if (issueType === jiraConfig.issueTypes.TEST_CASE) {
        return tracker.hasStage(ticket, 'IN_REVIEW_FAILED', jiraConfig.statuses.IN_REVIEW_FAILED)
            ? jiraConfig.statuses.FAILED
            : jiraConfig.statuses.PASSED;
    }
    return jiraConfig.statuses.IN_TESTING;
}

function markTestPrMerged(ticketKey) {
    try {
        getTracker().addLabel(ticketKey, LABELS.TEST_PR_MERGED);
        console.log('Added label', LABELS.TEST_PR_MERGED, 'to', ticketKey);
    } catch (e) {
        console.warn('Could not add test_pr_merged label:', e);
    }
}

function finalizeAlreadyMergedTestCase(ticketKey, branchName, issueType, jiraConfig) {
    try {
        markTestPrMerged(ticketKey);
        const ticket = getTracker().getIssue(ticketKey);
        const finalStatus = resolveFinalStatus(ticket, issueType, jiraConfig, getTracker());
        // gh-916: the final status (Passed/Failed/In Testing) can be tag-only — stage-label fallback.
        const moved = getTracker().moveToStatusOrMark(ticketKey, finalStatus,
            issueType === jiraConfig.issueTypes.TEST_CASE
                ? (finalStatus === jiraConfig.statuses.FAILED ? 'FAILED' : 'PASSED')
                : 'IN_TESTING');
        if (moved.moved || moved.marked) {
            getTracker().postComment(ticketKey, 'h3. ✅ Test Code Already Merged\n\n' +
                    'Branch {code}' + branchName + '{code} has no commits ahead of main, so the test code is already in main.\n\n' +
                    'Moved ticket to *' + finalStatus + '* and removed the stale branch.');
            console.log('✅ Branch has no commits ahead of main — moved', ticketKey, 'to', finalStatus);
        }
        try {
            cli_execute_command({ command: 'git push origin --delete ' + branchName });
            console.log('✅ Deleted stale branch:', branchName);
        } catch (delErr) {
            console.warn('Could not delete stale branch', branchName + ':', delErr);
        }
    } catch (e) {
        console.warn('Failed to finalize already-merged test case:', e);
    }
}

function action(params) {
    try {
        const ticketKey = getTicketKey(params);
        const inputFolder = getInputFolder(params, ticketKey);
        const issueType = getIssueType(params);
        var config = configLoader.loadProjectConfig(params.jobParams || params);
        initTracker(config, (params.jobParams && params.jobParams.customParams) || params.customParams || {});
        var jiraConfig = config.jira;
        var scm = configLoader.createScm(config);

        console.log('=== Preparing test PR for review:', ticketKey, '===');

        ensureInputFolder(inputFolder);
        clearStaleReviewOutputs();

        // Step 1: GitHub repo info
        var repoInfo = scm.getRemoteRepoInfo();
        if (!repoInfo) {
            postReviewSetupFailed(ticketKey, 'Could not determine repository from git remote', '_Review cancelled._');
            return false;
        }

        // Step 2: Find PR on test/{KEY} branch specifically
        var found = findTestPRForTicket(scm, ticketKey);
        if (!found) {
            // No open/merged PR — re-automate, or create a review PR for the existing branch
            var ensured = ensureReviewPrExists(scm, ticketKey, config, jiraConfig, issueType);
            if (ensured.result !== undefined) return ensured.result;
            found = ensured.found;
        }

        // If PR is already merged — move ticket to final status without re-reviewing
        if (found.merged) {
            handleAlreadyMergedPr(ticketKey, found.pr, issueType, jiraConfig);
            return false;
        }

        const pr = found.pr;

        // Skip WIP / draft PRs
        if (isWip(pr, params.ticket)) {
            console.log('PR #' + pr.number + ' is WIP/draft — skipping review for', ticketKey);
            try {
                getTracker().postComment(ticketKey, 'h3. ⏸️ Test PR Review Skipped\n\nPR [#' + pr.number + '|' + (pr.html_url || '') + '] is WIP/draft. Review will run once it is ready.');
            } catch (e) {}
            return false;
        }

        // Step 3: PR details
        const prDetails = gh.getPRDetails(scm, pr.number);
        if (!prDetails) {
            postReviewSetupFailed(ticketKey, 'Could not fetch details for PR #' + pr.number + '.', '_Review cancelled._');
            return false;
        }

        const branchName = prDetails.head ? prDetails.head.ref : null;

        // If the PR has no actual changes, the test code is already in main. Finalize and skip review.
        if (hasNoChanges(prDetails)) {
            console.log('PR #' + pr.number + ' has 0 changed files — test code is already in main');
            finalizeAlreadyMergedTestCase(ticketKey, branchName || ('test/' + ticketKey), issueType, jiraConfig);
            return false;
        }

        // Step 4: Checkout test branch
        try {
            if (branchName) {
                gitOps.checkoutPRBranch(branchName, config.workingDir, config.git.baseBranch);
            }
        } catch (e) {
            console.warn('Could not checkout test branch:', e);
        }

        // Step 5: Diff + discussions
        const baseBranch = prDetails.base ? prDetails.base.ref : config.git.baseBranch;
        const diff = gitOps.getPRDiff(baseBranch, branchName || (prDetails.head && prDetails.head.ref));

        console.log('Fetching PR discussions...');
        const discussionData = gh.fetchDiscussionsAndRawData(scm, pr.number);

        // Step 6: Write context files
        gitOps.writePRContext(inputFolder, prDetails, diff, discussionData.markdown, discussionData.rawThreads);

        // Step 7: Jira comment
        try {
            getTracker().postComment(ticketKey, 'h3. 🧪 Automated Test PR Review Started\n\n' +
                    '*Pull Request*: [PR #' + prDetails.number + '|' + prDetails.html_url + ']\n' +
                    '*Branch*: {code}' + (branchName || 'unknown') + '{code}\n' +
                    '*Files Changed*: ' + (prDetails.changed_files || 0) + '\n\n' +
                    '_Test code review results will be posted shortly..._');
        } catch (e) {
            console.warn('Failed to post Jira comment:', e);
        }

        console.log('✅ Test PR review setup complete — PR #' + prDetails.number);

        return {
            success: true,
            prNumber: prDetails.number,
            prUrl: prDetails.html_url,
            branchName: branchName,
            owner: repoInfo.owner,
            repo: repoInfo.repo
        };

    } catch (error) {
        console.error('❌ Error in prepareTestPRForReview:', error);
        try {
            const ticketKey = getTicketKey(params);
            getTracker().postComment(ticketKey, 'h3. ❌ Test PR Review Setup Error\n\n{code}' + error.toString() + '{code}');
        } catch (e) {}
        return false;
    }
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        action: action,
        isWip: isWip,
        isWipPr: isWipPr,
        isWipPrTitle: isWipPrTitle,
        ticketLabels: ticketLabels,
        isWipLabel: isWipLabel,
        hasWipTicketLabel: hasWipTicketLabel
    };
}

// Coverage runner for the crap4js quality gate (dmtools-agents).
//
// Executes the node test harness (js/unit-tests/node_testRunner.js) against
// the nyc-INSTRUMENTED copy of the repo and dumps global.__coverage__ in
// Istanbul coverage-final.json format for crap4js.
//
// Why the dance: the harness loads every module through its own
// loadModule()/eval() (mock injection), which bypasses nyc's require hook —
// a plain `nyc node node_testRunner.js` instruments nothing. Pre-instrumenting
// the tree with `nyc instrument` bakes the Istanbul counters into the sources
// themselves, so eval'd code reports coverage through the global.
//
// Usage:
//   node ci/run_with_coverage.js <runner.js> <coverage-out.json> [testFiles...]
//
// Exit code = the harness's exit code (0 = all tests passed). Coverage is
// written regardless of test failures — the canonical suite green-gate is
// the pack-release test job (`dmtools run js/unit-tests/run_all.json`);
// this node harness is a coverage vehicle, and its known mock gaps
// (see the quality workflow) must not block coverage collection.

const fs = require('fs');
const path = require('path');

const runner = process.argv[2];
const outFile = process.argv[3];
const testFiles = process.argv.slice(4);

const origExit = process.exit;
let exitCode = 0;
process.exit = (c) => { exitCode = c || 0; throw { __coverage_exit__: true }; };
process.argv = [process.argv[0], runner].concat(testFiles);

try {
  require(runner);
} catch (e) {
  if (!e || !e.__coverage_exit__) {
    console.error(e);
    origExit(2);
  }
}
fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, JSON.stringify(global.__coverage__ || {}));
console.log('coverage written: ' + outFile + ' (' +
  Object.keys(global.__coverage__ || {}).length + ' files)');
origExit(exitCode);
