        var m = loadHelpers();
        assert.equal(m.isRetryPendingReason('ci_running'), true);
        assert.equal(m.isRetryPendingReason('behind'), true);
        assert.equal(m.isRetryPendingReason('not_ready'), true);
        assert.equal(m.isRetryPendingReason('conflict'), false);
