function stats(file, label) {
  var fs=require('fs');
  var lines=fs.readFileSync(file,'utf8').split('\n');
  var rows=[]; var max=-1; var maxName='';
  for (var i=3;i<lines.length;i++){
    var l=lines[i].trim(); if(!l) continue;
    var c=l.split(/\s+/); if(c.length<5) continue;
    var crap=parseFloat(c[c.length-1]); if(isNaN(crap)) continue;
    var fn=c[0], fileP=c[1];
    if(/\/(unit-tests|test|integration-tests)\//.test(fileP)) continue;
    if (/\.test\.|_test\.|testRunner|node_testRunner/.test(fileP)) continue;
    rows.push({fn:fn,file:fileP,crap:crap});
    if(crap>max){max=crap;maxName=fn+' '+fileP;}
  }
  var over8=rows.filter(function(r){return r.crap>8});
  console.log(label+': measured='+rows.length+' max='+max+' ('+maxName+') over8='+over8.length);
}
stats('/tmp/crap-before.txt','BEFORE');
stats('/tmp/crap-after.txt','AFTER ');
